-- V1.0.49：种子 5 本词书（由 scripts/generate-word-book-seed.mjs 生成，请勿手改）
-- 目标库：exercise_db
-- 风险：低（纯 DML；新增 5 本词书 + 词书明细，不影响存量数据）
-- 回滚：
--   DELETE FROM word_book_item WHERE book_code IN ('basic_500','cet4_outline','cet6_outline','cet4_high','cet6_high');
--   DELETE FROM word_book WHERE code IN ('basic_500','cet4_outline','cet6_outline','cet4_high','cet6_high');
-- 说明：
--   1. rank_no 来自 ECDICT book_word.sort_no 书内升序名次（1 为词频最高）。
--   2. CET6 为增量（排除已在 CET4 词书内的词），增量内重新从 1 排名。
--   3. 末尾清理 word 不在 word_dictionary 中的词，保证词卡降级可查到释义。

-- 词书种子数据（由 scripts/generate-word-book-seed.mjs 生成，请勿手改）
