-- 对齐：清理不在 word_dictionary 中的词（book_word 与 word_dictionary 词集有少量差异）
-- 注意：word_dictionary 实际排序规则为 utf8mb4_0900_ai_ci（MySQL 8 默认），
--       与 V1.0.0 脚本声明的 utf8mb4_unicode_ci 不一致，
--       跨表比较必须显式 COLLATE，否则报 1267 Illegal mix of collations。
DELETE FROM word_book_item
WHERE word COLLATE utf8mb4_0900_ai_ci NOT IN (
  SELECT word COLLATE utf8mb4_0900_ai_ci FROM word_dictionary
);
